import{_ as a,c as e,o as s,ag as t}from"./chunks/framework.DQvKz0xt.js";const m=JSON.parse('{"title":"单独显示 (Solos) - Rive 编辑器","description":"单独显示 (Solos) 类似于组（Group），但它增加了一个特殊功能：能够切换其内部嵌套对象的渲染状态，每次仅显示一个子对象。 Solo 非常适合用于处理具有多种状态或视角的对象。例如，一个角色的不同手势、不同朝向的脸部，或是一个开关的不同视觉状态。","frontmatter":{"title":"单独显示 (Solos) - Rive 编辑器","description":"单独显示 (Solos) 类似于组（Group），但它增加了一个特殊功能：能够切换其内部嵌套对象的渲染状态，每次仅显示一个子对象。 Solo 非常适合用于处理具有多种状态或视角的对象。例如，一个角色的不同手势、不同朝向的脸部，或是一个开关的不同视觉状态。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 形状操控, 单独显示"}]]},"headers":[],"relativePath":"editor/manipulating-shapes/solos.md","filePath":"editor/manipulating-shapes/solos.md","lastUpdated":1774838907000}'),i={name:"editor/manipulating-shapes/solos.md"};function l(r,o,p,n,h,d){return s(),e("div",null,[...o[0]||(o[0]=[t('<p>操控形状</p><h1 id="单独显示-solos" tabindex="-1">单独显示 (Solos) <a class="header-anchor" href="#单独显示-solos" aria-label="Permalink to &quot;单独显示 (Solos)&quot;">​</a></h1><p>单独显示 (Solos) 类似于组（Group），但它增加了一个特殊功能：能够切换其内部嵌套对象的渲染状态，每次仅显示一个子对象。</p><h2 id="​-什么是-solo" tabindex="-1"><a href="#what-is-a-solo">​</a> 什么是 Solo <a class="header-anchor" href="#​-什么是-solo" aria-label="Permalink to &quot;[​](#what-is-a-solo) 什么是 Solo&quot;">​</a></h2><p>Solo 非常适合用于处理具有多种状态或视角的对象。例如，一个角色的不同手势、不同朝向的脸部，或是一个开关的不同视觉状态。</p><p><img src="https://help.rive.app/images/solos-example.gif" alt="Solo 示例 Pn"></p><h2 id="​-如何使用" tabindex="-1"><a href="#how-to-use">​</a> 如何使用 <a class="header-anchor" href="#​-如何使用" aria-label="Permalink to &quot;[​](#how-to-use) 如何使用&quot;">​</a></h2><p>将多个对象放入 Solo 后，你可以在检查器中看到一个列表。点击列表中的项即可切换当前显示的对象。在动画模式下，这个切换过程可以被设为关键帧。</p><p><a href="/docs/editor/manipulating-shapes/clipping">裁剪 (Clipping)</a><a href="/docs/editor/manipulating-shapes/trim-path">路径裁剪 (Trim Path)</a></p>',9)])])}const u=a(i,[["render",l]]);export{m as __pageData,u as default};
